import numpy as np
from IPython.display import Audio, display

sr = 22050

def click(freq, gain=1.0, length=0.05):
    tt = np.linspace(0, length, int(sr * length), endpoint=False)
    return gain * np.sin(2 * np.pi * freq * tt) * np.exp(-tt / 0.005)

def render(pattern, pulse, beat_every=None, repeats=4):
    """pattern: string of x (onset) and . (rest), one character per pulse."""
    n = len(pattern)
    total = n * pulse * repeats + 0.3
    buf = np.zeros(int(sr * total))
    for r in range(repeats):
        for k, ch in enumerate(pattern):
            i = int((r * n + k) * pulse * sr)
            c = click(1200, gain=0.15)                       # quiet pulse click
            if beat_every and k % beat_every == 0:
                c = click(600, gain=0.5)                     # low click on main beats
            if ch == "x":
                c = c + click(2500, gain=1.0)                # pattern onset
            buf[i:i + len(c)] += c
    return buf / np.max(np.abs(buf)) * 0.3

patterns = [
    ("Tresillo, 3+3+2 over 8 pulses",                  "x..x..x.",          0.15, None),
    ("Rachenitsa, 2+2+3 over 7 pulses (7/8)",          "x.x.x..",           0.16, None),
    ("Standard bell pattern, 12 pulses, 4 beats",      "x.x.xx.x.x.x",      0.12, 3),
    ("Son clave (3-2), 16 pulses, 4 beats",            "x..x..x...x.x...",  0.12, 4),
]

for name, pattern, pulse, beat_every in patterns:
    print(f"{name}:  {pattern}")
    display(Audio(render(pattern, pulse, beat_every), rate=sr))
